/**
 * Which column of a Guardian chip's upgrade table holds the cost of a track.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    GUARDIAN_IRREGULAR_COST_COLUMNS, guardianCostColumn
 * depends    src/support/own-lookup
 * used by    src/calculators/specs.generated, src/knowledge/compartments/guardian, src/mechanics/guardians/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { ownLookupOr } from '../../support/own-lookup'

/**
 * The cost column for a track is USUALLY `<track>Cost`, and twice it is not.
 *
 * `attack.percentage` is paid for by `attackCost` and `ally.recoveryAmount` by `recoveryCost`.
 * Both are the chip's headline stat, so a lookup that builds the cost key by convention misses
 * exactly the two tracks a player most wants costed — and if the miss defaults to zero, the two
 * most expensive things the Guardian sells read as free.
 */
export const GUARDIAN_IRREGULAR_COST_COLUMNS: Readonly<Record<string, string>> = {
  percentage: 'attackCost',
  recoveryAmount: 'recoveryCost',
}

export function guardianCostColumn(track: string): string {
  return ownLookupOr(GUARDIAN_IRREGULAR_COST_COLUMNS, track, `${track}Cost`)
}
